INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 6, 'theory', 'Quiz: system calls');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 0, 'How does an ordinary program get into the kernel?', '["By calling a kernel function directly at a known address", "By reading kernel memory through mmap", "With the syscall instruction: call number in rax, arguments in registers, and the CPU switches to kernel mode", "By writing the call number to the file /dev/kernel"]', 2, 'The only legitimate way up from user mode is a system call; anything else raises an exception.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 1, 'What does read return when the file has ended?', '["Zero", "-1 with the error code EOF", "The byte count of the previous call", "The call blocks forever"]', 0, 'Zero means end of file. Any number smaller than requested is also normal, which is why reading usually happens in a loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 2, 'What is the vDSO for?', '["Running drivers in user mode", "Protecting calls from interception", "Verifying module signatures", "Some frequent calls, such as getting the time, run without entering the kernel"]', 3, 'The kernel maps a page with code and time data into the process; the read stays in user mode and takes a few nanoseconds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 3, 'What does strace -c show?', '["The program''s memory usage", "A summary: how many times each system call was made and how much time it took", "A list of loaded libraries", "Only the calls that failed"]', 1, 'Plain strace prints every call with its arguments, while the -c option collects totals, which is handy for spotting thousands of tiny reads.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 4, 'What is the main advantage of io_uring?', '["Two shared rings for requests and results: a batch of operations goes out in one call or with no calls at all", "It replaces the file system", "It turns on I/O encryption", "It works only for network sockets"]', 0, 'Fewer transitions into the kernel means higher throughput with thousands of simultaneous operations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 5, 'What does a libc wrapper return when the system call failed?', '["The negative error code as is", "Zero and a message on stderr", "The value -1, with the reason stored in the errno variable", "It terminates the program with a signal"]', 2, 'The kernel returns the error as a number, and the wrapper turns it into the familiar "-1 and errno", so you must read errno right after the failed call.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 6, 'The call read(fd, buf, 4096) returned 100. What does it mean?', '["A read error occurred", "100 bytes were read: a partial read is normal, and you call read again for the rest", "The file is exactly 100 bytes and will never grow", "The kernel rounded the request size"]', 1, 'The number is how many bytes were read this time. Zero means end of file, while less than requested is a perfectly normal answer for a pipe, socket, or terminal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 6, 7, 'What does the kernel do if a program passes an invalid pointer to a system call?', '["Reads at that address and crashes immediately", "Reboots the system", "Silently substitutes a null address", "Checks access and returns the EFAULT error, not trusting an address from user memory"]', 3, 'The system call boundary is a trust boundary: everything that comes from user space, the kernel checks.');
